-- Additional engine-family references transcribed from public official Cat Parts Store category pages.
-- These are search references only. Fitment is recorded only where the Cat listing explicitly names the engine.
on conflict (part_number) do update set
 name=excluded.name,description=excluded.description,engine_models=excluded.engine_models,
 technical_group=excluded.technical_group,source_name=excluded.source_name,source_url=excluded.source_url,
 source_note=excluded.source_note,verification_status='REFERENCE',image_url=coalesce(public.part_catalog.image_url,excluded.image_url),
 specifications=excluded.specifications,compatible_models=excluded.compatible_models,updated_at=now();
